/* csp/ringbuffer.h */

#include <compare>

namespace csp::detail {

template <typename T>
class RingBuffer {
public:
    static constexpr size_t npos = size_t(-1);

    explicit RingBuffer(size_t capacity = npos)
        : capacity_(capacity)
        , size_(round_up_pow2(capacity == npos ? 4 : capacity))
        , mask_(size_ - 1)
        , data_(alloc(size_))
    { }

    ~RingBuffer() {
        clear();
        dealloc(data_);
    }

    RingBuffer(RingBuffer const &) = delete;
    RingBuffer & operator=(RingBuffer const &) = delete;

    RingBuffer(RingBuffer && o) noexcept
        : capacity_(o.capacity_)
        , size_(o.size_)
        , mask_(o.mask_)
        , front_(o.front_)
        , back_(o.back_)
        , count_(o.count_)
        , data_(std::exchange(o.data_, nullptr))
    {
        o.count_ = 0;
        o.front_ = o.back_ = 0;
    }

    RingBuffer & operator=(RingBuffer && o) noexcept {
        if (this != &o) {
            clear();
            dealloc(data_);
            capacity_ = o.capacity_;
            size_ = o.size_;
            mask_ = o.mask_;
            front_ = o.front_;
            back_ = o.back_;
            count_ = o.count_;
            data_ = std::exchange(o.data_, nullptr);
            o.count_ = 0;
            o.front_ = o.back_ = 0;
        }
        return *this;
    }

    size_t count() const { return count_; }
    bool empty() const { return !count_; }
    bool full() const { return count_ == capacity_; }
    T & front() const { return data_[front_]; }

    void * next() {
        if (count_ == size_) {
            assert(capacity_ == npos);
            grow();
        }
        return &data_[back_];
    }

    void push() {
        back_ = (back_ + 1) & mask_;
        ++count_;
    }

    void push(T t) {
        new (next()) T{std::move(t)};
        push();
    }

    template <typename... Args>
    void emplace(Args &&... args) {
        new (next()) T{std::forward<Args>(args)...};
        push();
    }

    void pop() {
        assert(!empty());
        data_[front_].~T();
        front_ = (front_ + 1) & mask_;
        --count_;
    }

    bool remove(T t) {
        for (size_t i = 0; i < count_; ++i) {
            if (data_[(front_ + i) & mask_] == t) {
                if (i == 0) {
                    pop();
                } else if (i == count_ - 1) {
                    back_ = (back_ - 1) & mask_;
                    data_[back_].~T();
                    --count_;
                } else {
                    // Fill hole from back.
                    back_ = (back_ - 1) & mask_;
                    data_[(front_ + i) & mask_] = std::move(data_[back_]);
                    data_[back_].~T();
                    --count_;
                }
                return true;
            }
        }
        return false;
    }

    void clear() {
        while (!empty()) pop();
    }

    class iterator {
    public:
        using value_type = T;
        using reference = T &;
        using pointer = T *;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::random_access_iterator_tag;

        iterator() = default;

        reference operator*() const { return buf_->data_[(buf_->front_ + idx_) & buf_->mask_]; }
        pointer operator->() const { return &**this; }
        reference operator[](difference_type n) const { return *(*this + n); }

        iterator & operator++() { ++idx_; return *this; }
        iterator operator++(int) { auto t = *this; ++*this; return t; }
        iterator & operator--() { --idx_; return *this; }
        iterator operator--(int) { auto t = *this; --*this; return t; }

        iterator & operator+=(difference_type n) { idx_ += n; return *this; }
        iterator & operator-=(difference_type n) { idx_ -= n; return *this; }
        iterator operator+(difference_type n) const { auto t = *this; return t += n; }
        iterator operator-(difference_type n) const { auto t = *this; return t -= n; }
        friend iterator operator+(difference_type n, iterator i) { return i += n; }
        difference_type operator-(iterator const & o) const {
            return static_cast<difference_type>(idx_) - static_cast<difference_type>(o.idx_);
        }

        bool operator==(iterator const & o) const = default;
        std::strong_ordering operator<=>(iterator const & o) const { return idx_ <=> o.idx_; }

    private:
        friend class RingBuffer;
        RingBuffer const * buf_ = nullptr;
        size_t idx_ = 0;
        iterator(RingBuffer const * buf, size_t idx) : buf_(buf), idx_(idx) { }
    };

    iterator begin() const { return {this, 0}; }
    iterator end() const { return {this, count_}; }

private:
    size_t capacity_;
    size_t size_;
    size_t mask_;
    size_t front_ = 0;
    size_t back_ = 0;
    size_t count_ = 0;
    T * data_;

    static T * alloc(size_t n) {
        return static_cast<T *>(::operator new(n * sizeof(T), std::align_val_t(alignof(T))));
    }

    static void dealloc(T * p) {
        if (p) ::operator delete(p, std::align_val_t(alignof(T)));
    }

    static constexpr size_t round_up_pow2(size_t n) {
        assert(n > 0);
        return std::bit_ceil(n);
    }

    void grow() {
        size_t new_size = size_ * 2;
        T * newdata = alloc(new_size);
        for (size_t i = 0; i < count_; ++i) {
            new (&newdata[i]) T{std::move(data_[(front_ + i) & mask_])};
            data_[(front_ + i) & mask_].~T();
        }
        dealloc(data_);
        data_ = newdata;
        size_ = new_size;
        mask_ = new_size - 1;
        front_ = 0;
        back_ = count_;
    }
};

}


namespace csp::part {

// Bounded (or unbounded) FIFO buffer between producer and consumer.
// Decouples production rate from consumption rate up to the given capacity.
template <typename T>
auto buffer(size_t capacity = size_t(-1)) {
    if (capacity == 0) {
        throw std::invalid_argument("buffer capacity must be at least 1");
    }
    return make_filter<T>([capacity](reader<T> in, writer<T> out) {
        internal::descr("buffer");

        static Logger log("chan/buffer");
        static Logger scope("chan/buffer/scope");
        BRAC_SCOPE(scope, "buffer", "%lu", capacity);

        csp::detail::RingBuffer<T> buf(capacity);
        for (;;) {
            CSP_LOG(log, "buffer state: %s", buf.empty() ? "EMPTY" : buf.full() ? "FULL" : "JUST RIGHT");
            switch (auto slot = alt(buf.full()  ? ~in  : in  >> buf.next(),
                                    buf.empty() ? ~out : out << buf.front())) {
            case 0:
                CSP_LOG(log, "IN");
                buf.push();
                CSP_LOG(log, "PUSH%s", buf.full() ? " (full)" : "");
                break;
            case ~0:
                CSP_LOG(log, "DRAIN");
                while (!buf.empty() && out << std::move(buf.front())) {
                    buf.pop();
                }
                return;
            case 1:
                CSP_LOG(log, "OUT");
                buf.pop();
                CSP_LOG(log, "POP %s", buf.empty() ? " (empty)": "");
                break;
            case ~1:
                CSP_LOG(log, "~OUT");
                return;
            default:
                __builtin_unreachable();
            }
        }
    });
}

}

/* csp/part/chain.h */



namespace csp::part {

// Concatenate multiple readers into a single sequential stream.
// Reads each input to exhaustion in order, then moves to the next.
template <typename T, typename R,
          typename = decltype(std::begin(std::declval<R>())->read())>
auto chain(R rr) {
    return make_producer<T>([rr = std::move(rr)](writer<T> w) {
        internal::descr("chain");

        static Logger scope("chan/chain/scope");
        BRAC_SCOPE(scope, "chain", "%d readers", rr.size());

        static Logger log("chan/chain/log");

        for (auto & r : rr) {
            for (T n; csp::alt(r >> n, ~w) == 0;) {
                CSP_LOG(log, "loop");
                if (!(w << std::move(n))) {
                    break;
                }
            }
            CSP_LOG(log, "next in");
        }
    });
}

}

/* csp/part/chunk_by.h */



namespace csp::part {

// Group consecutive elements where pred(prev, curr) is true.
// Emits each group as a vector. Flushes the final group on input exhaustion.
template <typename T, typename F>
auto chunk_by(F&& f) {
    return make_filter<T, std::vector<T>>(
        [f = std::forward<F>(f)]
        (reader<T> in, writer<std::vector<T>> out) {
            internal::descr("chunk_by");
            std::vector<T> chunk;
            for (T t; csp::alt(in >> t, ~out) == 0;) {
                if (!chunk.empty() && !f(chunk.back(), t)) {
                    if (!(out << std::move(chunk))) return;
                    chunk.clear();
                }
                chunk.push_back(std::move(t));
            }
            if (!chunk.empty())
                out << std::move(chunk);
        });
}

}

